+import { type Api, type ModelKind, runnerApiKind } from "@oh-my-pi/pi-catalog/types";
+import { isJudgmentApi } from "../judgment/native";
+import { isSpeechApi } from "../speech";
+
+/** Image APIs `/v1/images/*` serves; the hosted Responses pair needs a carrier model the gateway cannot resolve. */
+const GATEWAY_IMAGE_APIS: Readonly<Partial<Record<Api, true>>> = {
+	"openai-images": true,
+	"openrouter-images": true,
+	"google-generative-ai": true,
+	"google-gemini-cli": true,
+	"factory-droid-agent": true,
+};
+
+/**
+ * Whether the gateway route for a model of `kind` accepts `api`. The routes answer `400` for any other API, so
+ * the served catalog and stdio fallback chains use this to skip models no route can run. On-device
+ * `local-inference` runners never qualify.
+ */
+export function gatewayRouteAccepts(kind: ModelKind, api: Api): boolean {
+	switch (kind) {
+		case "chat":
+			return api !== "local-inference";
+		case "judge":
+			return isJudgmentApi(api);
+		case "image":
+			return GATEWAY_IMAGE_APIS[api] === true;
+		case "tts":
+			return isSpeechApi(api);
+		case "stt":
+			return runnerApiKind(api) === "stt";
+		case "embedding":
+			return api === "openai-embeddings";
+		case "rerank":
+			return api === "openrouter-rerank";
+		case "video":
+			return api === "openrouter-video";
+		default:
+			return false;
+	}
+}

+import { transcribeOpenAICodex } from "./openai-codex-transcriptions";
+export * from "./openai-codex-transcriptions";
+	if (model.api === "openai-codex-transcriptions") return transcribeOpenAICodex(model, request, options);

+import { type } from "@oh-my-pi/omptype";
+import type { Api, Model } from "@oh-my-pi/pi-catalog/types";
+import {
+	applyCodexResidencyHeader,
+	CODEX_DESKTOP_ORIGINATOR,
+	CODEX_DESKTOP_USER_AGENT,
+	getCodexAccountId,
+	OPENAI_HEADERS,
+} from "@oh-my-pi/pi-catalog/wire/codex";
+import { withAuth } from "../auth-retry";
+import * as AIError from "../error";
+import { emptyUsage } from "../images/shared";
+import { getCodexAttestationHeader } from "../providers/openai-codex-attestation";
+import { isChatGptBaseUrl, normalizeCodexBaseUrl } from "../usage/openai-codex-base-url";
+import { type TranscriptionOptions, transcriptionResponseError } from "./openai-transcriptions";
+import { TRANSCRIPTION_AUDIO_MIME_TYPES, type TranscriptionRequest, type TranscriptionResult } from "./types";
+
+const responseSchema = type({ text: "string" });
+
+/** Extensions the endpoint decodes. */
+const DECODABLE_EXTENSIONS: Readonly<Record<string, true>> = {
+	wav: true,
+	mp3: true,
+	mpeg: true,
+	mp4: true,
+	m4a: true,
+	ogg: true,
+	webm: true,
+	flac: true,
+};
+
+/** MIME spellings browsers report for containers the table names differently. */
+const MIME_ALIASES: Readonly<Record<string, string>> = {
+	"audio/m4a": "audio/mp4",
+	"audio/mp3": "audio/mpeg",
+	"audio/opus": "audio/ogg",
+};
+
+/** The table's first extension for `mimeType`: its canonical name for that container. */
+function containerExtension(mimeType: string | undefined): string | undefined {
+	return mimeType
+		? Object.entries(TRANSCRIPTION_AUDIO_MIME_TYPES).find(([, mime]) => mime === mimeType)?.[0]
+		: undefined;
+}
+
+/**
+ * The endpoint picks its decoder from the upload's file extension and answers `500 Error in ASR API` when the
+ * extension is missing or unknown (`voice.oga`, `audio`), even for audio it can decode. Keep a decodable name
+ * whose container agrees with the MIME type (`mp3`/`mpeg`, `m4a`/`mp4` share one MIME type); otherwise name the
+ * file after the container the MIME type declares. A generic or empty MIME type declares nothing, so a known
+ * suffix names the container instead (`voice.oga` → `audio.ogg`); with neither, the caller's name is kept.
+ */
+function uploadFileName(request: TranscriptionRequest): string {
+	const name = request.fileName?.trim() || "audio";
+	const dot = name.lastIndexOf(".");
+	const extension = dot >= 0 ? name.slice(dot + 1).toLowerCase() : "";
+	const rawMime = request.mimeType.split(";", 1)[0]?.trim().toLowerCase().replace("audio/x-", "audio/") ?? "";
+	const mimeType = MIME_ALIASES[rawMime] ?? rawMime;
+	const declared = containerExtension(mimeType);
+	if (
+		DECODABLE_EXTENSIONS[extension] === true &&
+		(!declared || TRANSCRIPTION_AUDIO_MIME_TYPES[extension] === mimeType)
+	) {
+		return name;
+	}
+	const container = declared ?? containerExtension(TRANSCRIPTION_AUDIO_MIME_TYPES[extension]);
+	return container ? `audio.${container}` : name;
+}
+
+/**
+ * Transcribe through the ChatGPT backend dictation endpoint (`POST /transcribe`) with a Codex OAuth bearer.
+ *
+ * The endpoint takes only `file` and `language` and reports no usage or segments, so prompt, temperature,
+ * response format and timestamp options are not forwarded and the result carries text with zero usage.
+ *
+ * A `baseUrl` that is not on the ChatGPT origin is refused: it means `providers.openai-codex` points at a relay,
+ * and the key configured for that relay outranks the stored OAuth login, so sending it to chatgpt.com would
+ * disclose it and fail anyway.
+ */
+export async function transcribeOpenAICodex(
+	model: Model<Api>,
+	request: TranscriptionRequest,
+	options: TranscriptionOptions,
+): Promise<TranscriptionResult> {
+	if (model.baseUrl?.trim() && !isChatGptBaseUrl(model.baseUrl)) {
+		throw new AIError.ConfigurationError(
+			`${model.provider}/${model.id} only runs on chatgpt.com, but its base URL is ${model.baseUrl}; remove the providers.${model.provider}.baseUrl override or pick another speech-to-text model`,
+		);
+	}
+	const form = new FormData();
+	form.append("file", new File([request.audio], uploadFileName(request), { type: request.mimeType }));
+	if (request.language !== undefined) form.append("language", request.language);
+
+	const fetchImpl = options.fetch ?? fetch;
+	const response = await withAuth(
+		options.apiKey,
+		async key => {
+			const headers: Record<string, string> = {
+				Authorization: `Bearer ${key}`,
+				Accept: "application/json",
+				"User-Agent": CODEX_DESKTOP_USER_AGENT,
+				[OPENAI_HEADERS.ORIGINATOR]: CODEX_DESKTOP_ORIGINATOR,
+			};
+			const accountId = getCodexAccountId(key);
+			if (accountId) headers[OPENAI_HEADERS.ACCOUNT_ID] = accountId;
+			const attestation = await getCodexAttestationHeader(accountId);
+			if (attestation) headers[OPENAI_HEADERS.ATTESTATION] = attestation;
+			// The backend 401s a region-pinned workspace unless the request declares its residency.
+			applyCodexResidencyHeader(headers, key);
+			const attempt = await fetchImpl(`${normalizeCodexBaseUrl(model.baseUrl)}/transcribe`, {
+				method: "POST",
+				headers,
+				body: form,
+				signal: options.signal,
+			});
+			if (!attempt.ok) throw await transcriptionResponseError(attempt, model);
+			return attempt;
+		},
+		{ signal: options.signal },
+	);
+
+	const parsed = responseSchema(await response.json());
+	if (parsed instanceof type.errors) {
+		throw new AIError.ProviderResponseError(
+			`${model.provider}/${model.id} transcription response is malformed: ${parsed.summary}`,
+			{ provider: model.provider, kind: "envelope" },
+		);
+	}
+	return { text: parsed.text, usage: emptyUsage() };
+}

+/** Upstream error bodies can be whole HTML pages (Cloudflare 403); only this much reaches the message. */
+const MAX_ERROR_DETAIL_LENGTH = 500;
+
+/** Map a non-2xx transcription response onto {@link TranscriptionApiError}; shared by every transcription transport. */
+export async function transcriptionResponseError(
+	response: Response,
+	model: Model<Api>,
+): Promise<TranscriptionApiError> {
+		if (parsed && typeof parsed === "object" && "detail" in parsed && typeof parsed.detail === "string") {
+			// ChatGPT backend error envelope: `{"detail":"Error in ASR API"}`.
+			detail = parsed.detail;
+		} else if (parsed && typeof parsed === "object" && "error" in parsed) {
+		`${model.provider}/${model.id} transcription API error (${response.status}): ${(detail || response.statusText).slice(0, MAX_ERROR_DETAIL_LENGTH)}`,
+			if (!attempt.ok) throw await transcriptionResponseError(attempt, model);

+	const origin = chatGptOrigin(baseUrl);
+	// wham/usage always lives at `${origin}/backend-api/...` on the canonical
+	// ChatGPT origin, so ignore any extra path (e.g. `/backend-api/codex/responses`
+	// from a streaming baseUrl) — otherwise we'd build `.../codex/responses/wham/usage`.
+	return origin ? `${origin}/backend-api` : CODEX_BASE_URL;
+}
+
+/** Whether `baseUrl` is on the canonical ChatGPT origin over HTTPS, the only host a Codex bearer may reach. */
+export function isChatGptBaseUrl(baseUrl: string): boolean {
+	return chatGptOrigin(baseUrl) !== undefined;
+}
+
+function chatGptOrigin(baseUrl?: string): string | undefined {
+	if (!trimmed) return undefined;
+		return undefined;
+	// The Codex bearer must never travel over plain HTTP.
+	if (parsed.protocol !== "https:" || (host !== "chatgpt.com" && host !== "chat.openai.com")) return undefined;
+	return parsed.origin;

+	storage.keys.setRuntime("openai-codex", "codex-secret");
+	const codex = transcriptionModel(
+		"openai-codex",
+		"codex-transcribe",
+		"openai-codex-transcriptions",
+		"https://chatgpt.com/backend-api",
+	);
+			if (id === codex.id || id === `openai-codex/${codex.id}`) return codex;
+	it("serves Codex subscription dictation through the ChatGPT /transcribe endpoint", async () => {
+		harness = await boot();
+		const response = await fetch(`${harness.url}/v1/audio/transcriptions`, {
+			method: "POST",
+			headers: gatewayHeaders("application/json"),
+			body: JSON.stringify({
+				model: "openai-codex/codex-transcribe",
+				input_audio: { data: AUDIO.toBase64(), format: "flac" },
+			}),
+		});
+
+		expect(response.status).toBe(200);
+		expect(await response.json()).toMatchObject({ text: UPSTREAM_RESULT.text });
+		expect(harness.upstream).toHaveLength(1);
+		expect(harness.upstream[0]).toMatchObject({
+			url: "https://chatgpt.com/backend-api/transcribe",
+			authorization: "Bearer codex-secret",
+			model: null,
+			fileName: "audio.flac",
+		});
+		expect(harness.upstream[0]?.audio).toEqual(AUDIO);
+	});
+

+import { afterEach, describe, expect, it, vi } from "bun:test";
+import { buildModel } from "@oh-my-pi/pi-catalog/build";
+import type { Api, FetchImpl, Model, ModelSpec } from "@oh-my-pi/pi-catalog/types";
+import * as codexAttestation from "@oh-my-pi/pi-ai/providers/openai-codex-attestation";
+import { TranscriptionApiError, transcribeAudio } from "@oh-my-pi/pi-ai/transcription";
+
+const AUDIO = new Uint8Array([0x66, 0x4c, 0x61, 0x43, 0x01, 0x02, 0x03, 0x04]);
+
+const model: Model<Api> = buildModel({
+	id: "codex-transcribe",
+	name: "Codex Dictation",
+	api: "openai-codex-transcriptions",
+	provider: "openai-codex",
+	baseUrl: "https://chatgpt.com/backend-api",
+	reasoning: false,
+	input: ["text"],
+	cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
+	contextWindow: null,
+	maxTokens: null,
+	kind: "stt",
+} satisfies ModelSpec<Api>);
+
+/** Unsigned JWT carrying the ChatGPT account claim the Codex backend routes on. */
+function codexToken(accountId: string): string {
+	const payload = btoa(JSON.stringify({ "https://api.openai.com/auth": { chatgpt_account_id: accountId } }));
+	return `header.${payload}.signature`;
+}
+
+describe("openai-codex-transcriptions transport", () => {
+	afterEach(() => {
+		vi.restoreAllMocks();
+	});
+
+	it("posts audio to the ChatGPT dictation endpoint as the Codex Desktop client", async () => {
+		const seen: Array<{ url: string; method?: string; headers: Headers; form: FormData }> = [];
+		const fetchImpl: FetchImpl = async (input, init) => {
+			if (!(init?.body instanceof FormData)) throw new Error("Expected multipart body");
+			seen.push({ url: String(input), method: init.method, headers: new Headers(init.headers), form: init.body });
+			return Response.json({
+				text: "Ask not.",
+				asset_pointer: "sediment://x",
+				asset_ttl: "30d",
+				asset_format: "flac",
+			});
+		};
+
+		const result = await transcribeAudio(
+			model,
+			{
+				audio: AUDIO,
+				mimeType: "audio/flac",
+				fileName: "jfk.flac",
+				language: "en",
+				prompt: "ignored",
+				temperature: 0.2,
+				responseFormat: "verbose_json",
+				timestampGranularities: ["word"],
+			},
+			{ apiKey: codexToken("acct-1"), fetch: fetchImpl },
+		);
+
+		expect(result.text).toBe("Ask not.");
+		expect(result.usage.cost.total).toBe(0);
+		expect(seen).toHaveLength(1);
+		const [request] = seen;
+		expect(request?.url).toBe("https://chatgpt.com/backend-api/transcribe");
+		expect(request?.method).toBe("POST");
+		// Cloudflare 403s the backend unless it sees the Codex Desktop identity.
+		expect(request?.headers.get("authorization")).toBe(`Bearer ${codexToken("acct-1")}`);
+		expect(request?.headers.get("chatgpt-account-id")).toBe("acct-1");
+		expect(request?.headers.get("originator")).toBe("Codex Desktop");
+		expect(request?.headers.get("user-agent")).toStartWith("Codex Desktop/");
+		// The endpoint takes only `file` and `language`; OpenAI-only fields are dropped.
+		expect([...(request?.form.keys() ?? [])]).toEqual(["file", "language"]);
+		const file = request?.form.get("file");
+		if (!(file instanceof File)) throw new Error("Expected audio file part");
+		expect(file.name).toBe("jfk.flac");
+		expect(new Uint8Array(await file.arrayBuffer())).toEqual(AUDIO);
+		expect(request?.form.get("language")).toBe("en");
+	});
+
+	it("renames an upload whose extension the endpoint cannot decode after its declared container", async () => {
+		// The backend answers 500 for Ogg/Opus unless the upload is named `*.ogg`; `.oga` and bare names fail.
+		const upload = async (fileName: string, mimeType: string): Promise<string | undefined> => {
+			let uploaded: string | undefined;
+			const fetchImpl: FetchImpl = async (_input, init) => {
+				const file = init?.body instanceof FormData ? init.body.get("file") : null;
+				uploaded = file instanceof File ? file.name : undefined;
+				return Response.json({ text: "ok" });
+			};
+			await transcribeAudio(
+				model,
+				{ audio: AUDIO, mimeType, fileName, responseFormat: "json" },
+				{ apiKey: codexToken("acct-1"), fetch: fetchImpl },
+			);
+			return uploaded;
+		};
+		expect(await upload("voice.oga", "audio/ogg")).toBe("audio.ogg");
+		// A decodable extension whose container contradicts the MIME type is renamed too: the decoder follows the name.
+		expect(await upload("clip.webm", "audio/ogg")).toBe("audio.ogg");
+		// Browser MIME aliases name their container: `audio/x-m4a` is M4A, `audio/mp3` and `audio/x-mp3` are MP3.
+		expect(await upload("blob", "audio/x-m4a")).toBe("audio.m4a");
+		expect(await upload("blob", "audio/mp3")).toBe("audio.mp3");
+		expect(await upload("blob", "audio/x-mp3")).toBe("audio.mp3");
+		// A generic or missing MIME type leaves the container to a known suffix.
+		expect(await upload("voice.oga", "application/octet-stream")).toBe("audio.ogg");
+		expect(await upload("voice.oga", "")).toBe("audio.ogg");
+		// Agreeing containers (including aliases) and unknown MIME types keep the caller's name.
+		expect(await upload("clip.mp3", "audio/mpeg")).toBe("clip.mp3");
+		expect(await upload("clip.mpeg", "audio/mpeg")).toBe("clip.mpeg");
+		expect(await upload("clip.m4a", "audio/mp4")).toBe("clip.m4a");
+		expect(await upload("clip.webm", "application/octet-stream")).toBe("clip.webm");
+	});
+
+	it("declares the token's workspace residency so a region-pinned workspace is not rejected", async () => {
+		const payload = btoa(
+			JSON.stringify({
+				"https://api.openai.com/auth": { chatgpt_account_id: "acct-1", chatgpt_data_residency: "us" },
+			}),
+		);
+		let residency: string | null | undefined;
+		const fetchImpl: FetchImpl = async (_input, init) => {
+			residency = new Headers(init?.headers).get("x-openai-internal-codex-residency");
+			return Response.json({ text: "ok" });
+		};
+		await transcribeAudio(
+			model,
+			{ audio: AUDIO, mimeType: "audio/wav", fileName: "dictation.wav", responseFormat: "json" },
+			{ apiKey: `header.${payload}.signature`, fetch: fetchImpl },
+		);
+		expect(residency).toBe("us");
+	});
+
+	it("attaches the host's DeviceCheck attestation like other Codex requests", async () => {
+		let attestation: string | null | undefined;
+		const fetchImpl: FetchImpl = async (_input, init) => {
+			attestation = new Headers(init?.headers).get("x-oai-attestation");
+			return Response.json({ text: "ok" });
+		};
+		vi.spyOn(codexAttestation, "getCodexAttestationHeader").mockResolvedValue("attest-envelope");
+		await transcribeAudio(
+			model,
+			{ audio: AUDIO, mimeType: "audio/wav", fileName: "dictation.wav", responseFormat: "json" },
+			{ apiKey: codexToken("acct-1"), fetch: fetchImpl },
+		);
+		expect(attestation).toBe("attest-envelope");
+	});
+
+	it("refuses a base URL off the ChatGPT HTTPS origin instead of sending its key anywhere", async () => {
+		let called = false;
+		const fetchImpl: FetchImpl = async () => {
+			called = true;
+			return Response.json({ text: "ok" });
+		};
+		// A relay's configured key outranks the OAuth login, so rewriting to chatgpt.com would disclose it.
+		for (const baseUrl of ["https://relay.example.com/v1", "http://chatgpt.com/backend-api"]) {
+			const failure = transcribeAudio(
+				{ ...model, baseUrl },
+				{ audio: AUDIO, mimeType: "audio/flac", fileName: "a.flac", responseFormat: "json" },
+				{ apiKey: "relay-key", fetch: fetchImpl },
+			);
+			await expect(failure).rejects.toThrow("only runs on chatgpt.com");
+		}
+		expect(called).toBe(false);
+	});
+
+	it("surfaces backend ASR failures as TranscriptionApiError with the upstream detail", async () => {
+		const fetchImpl: FetchImpl = async () => Response.json({ detail: "Error in ASR API" }, { status: 500 });
+		const failure = transcribeAudio(
+			model,
+			{ audio: AUDIO, mimeType: "audio/ogg", fileName: "clip.ogg", responseFormat: "json" },
+			{ apiKey: codexToken("acct-1"), fetch: fetchImpl },
+		);
+		await expect(failure).rejects.toBeInstanceOf(TranscriptionApiError);
+		await expect(failure).rejects.toMatchObject({
+			status: 500,
+			message: "openai-codex/codex-transcribe transcription API error (500): Error in ASR API",
+		});
+	});
+
+	it("bounds an HTML error page from Cloudflare instead of embedding it whole in the message", async () => {
+		const page = `<html>${"x".repeat(20_000)}</html>`;
+		const fetchImpl: FetchImpl = async () => new Response(page, { status: 403 });
+		const failure = transcribeAudio(
+			model,
+			{ audio: AUDIO, mimeType: "audio/wav", fileName: "dictation.wav", responseFormat: "json" },
+			{ apiKey: codexToken("acct-1"), fetch: fetchImpl },
+		);
+		await expect(failure).rejects.toMatchObject({
+			status: 403,
+			message: `openai-codex/codex-transcribe transcription API error (403): ${page.slice(0, 500)}`,
+		});
+	});
+
+	it("retries a 401 with the resolver's next credential and that credential's account", async () => {
+		const accounts: Array<string | null> = [];
+		const fetchImpl: FetchImpl = async (_input, init) => {
+			const headers = new Headers(init?.headers);
+			accounts.push(headers.get("chatgpt-account-id"));
+			if (accounts.length === 1) return Response.json({ detail: "Unauthorized" }, { status: 401 });
+			return Response.json({ text: "after refresh" });
+		};
+		const result = await transcribeAudio(
+			model,
+			{ audio: AUDIO, mimeType: "audio/wav", fileName: "dictation.wav", responseFormat: "json" },
+			{
+				apiKey: ctx => (ctx.error === undefined ? codexToken("acct-old") : codexToken("acct-new")),
+				fetch: fetchImpl,
+			},
+		);
+		expect(result.text).toBe("after refresh");
+		expect(accounts).toEqual(["acct-old", "acct-new"]);
+	});
+});

+		stt "openai-codex-transcriptions"
